'use strict';
let forumScope='community',forumThread='',forumLoading=false;
function forumEscape(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
async function forumRequest(path='',body){const response=await fetch('/api/forums'+path,{credentials:'same-origin',method:body?'POST':'GET',headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined}),data=await response.json();if(!response.ok)throw Error(data.error||'Forum unavailable.');return data;}
async function renderForums(){const el=document.querySelector('.page.active #allianceForumContent,.page.active #galaxyForumContent')||document.getElementById('forumContent');if(!el||forumLoading)return;forumLoading=true;try{if(forumThread){const data=await forumRequest('?thread='+encodeURIComponent(forumThread));el.innerHTML='<button class="btn button" data-forum-back>← TOPICS</button><section class="forum-thread"><h2>'+forumEscape(data.thread.title)+'</h2>'+data.posts.map(p=>'<article class="forum-post"><header><b>'+forumEscape(p.author_name)+'</b><time>'+new Date(p.created_at).toLocaleString()+'</time></header><p>'+forumEscape(p.body)+'</p></article>').join('')+(data.hasMore?'<button class="btn button" data-forum-more="'+data.nextOffset+'">LOAD MORE POSTS</button>':'')+'<form id="forumReplyForm"><label for="forumReplyBody">Reply</label><textarea id="forumReplyBody" name="body" rows="6" maxlength="20000" required></textarea><button class="btn button primary" type="submit">POST REPLY</button><p role="status" id="forumStatus"></p></form></section>';}else{const data=await forumRequest('?scope='+forumScope);el.innerHTML='<nav class="alliance-tabs forum-tabs" '+(['allianceForumContent','galaxyForumContent'].includes(el.id)?'hidden':'')+'><button class="btn button '+(forumScope==='community'?'active':'')+'" data-forum-scope="community">Community forum</button><button class="btn button '+(forumScope==='alliance'?'active':'')+'" data-forum-scope="alliance">Private alliance forum</button><button class="btn button" data-forum-scope="galaxy">Private galaxy forum</button></nav><div class="forum-topics">'+(data.threads.length?data.threads.map(t=>'<article class="forum-topic"><button class="forum-topic-link" data-forum-thread="'+t.id+'">'+forumEscape(t.title)+'</button><span>'+forumEscape(t.author_name)+' · '+t.posts+' posts</span><time>'+new Date(t.updated_at).toLocaleString()+'</time></article>').join(''):'<p>No topics yet. Start the first discussion.</p>')+'</div><section class="forum-compose"><h3>New topic</h3><form id="forumThreadForm"><label for="forumTopicTitle">Title</label><input id="forumTopicTitle" name="title" minlength="3" maxlength="120" required><label for="forumTopicBody">Message</label><textarea id="forumTopicBody" name="body" rows="7" maxlength="20000" required></textarea><button class="btn button primary" type="submit">CREATE TOPIC</button><p role="status" id="forumStatus"></p></form></section>';}}catch(error){el.innerHTML='<p class="notice">'+forumEscape(error.message)+'</p><button class="btn button" data-forum-scope="community">OPEN COMMUNITY FORUM</button>';}finally{forumLoading=false;}}
document.addEventListener('click',async e=>{const scope=e.target.closest('[data-forum-scope]'),thread=e.target.closest('[data-forum-thread]'),more=e.target.closest('[data-forum-more]');if(scope){forumScope=scope.dataset.forumScope;forumThread='';renderForums();}if(thread){forumThread=thread.dataset.forumThread;renderForums();}if(e.target.closest('[data-forum-back]')){forumThread='';renderForums();}if(more){try{const data=await forumRequest('?thread='+encodeURIComponent(forumThread)+'&offset='+more.dataset.forumMore);const holder=document.createElement('div');holder.innerHTML=data.posts.map(p=>'<article class="forum-post"><header><b>'+forumEscape(p.author_name)+'</b><time>'+new Date(p.created_at).toLocaleString()+'</time></header><p>'+forumEscape(p.body)+'</p></article>').join('');more.before(holder);if(data.hasMore)more.dataset.forumMore=data.nextOffset;else more.remove();}catch(error){more.textContent=error.message;}}});
document.addEventListener('submit',async e=>{if(!['forumReplyForm','forumThreadForm'].includes(e.target.id))return;e.preventDefault();const form=e.target,button=form.querySelector('button'),status=document.getElementById('forumStatus');button.disabled=true;try{const data=await forumRequest('',form.id==='forumThreadForm'?{action:'thread',scope:forumScope,title:form.elements.title.value,body:form.elements.body.value}:{action:'reply',threadId:forumThread,body:form.elements.body.value});if(data.id)forumThread=data.id;await refreshForumQuestCounts();renderForums();}catch(error){status.textContent=error.message;}finally{button.disabled=false;}});renderForums();

async function refreshForumQuestCounts(){if(typeof state==='undefined')return;try{const data=await forumRequest('?stats=1');state.forumQuestCounts=data.counts;autoClaimQuestRewards();save();renderQuests();}catch{}}if(typeof state!=='undefined')refreshForumQuestCounts();
document.addEventListener('click',e=>{const tab=e.target.closest('[data-atab="forums"]');if(tab){forumScope='alliance';forumThread='';renderForums();refreshForumQuestCounts();}});
